const peaceState={evidence:72,capacity:64,cooperation:58,protection:76};
const peaceLabels=[['TESTIMONY','證詞'],['EVIDENCE','證據'],['INVESTIGATION','調查'],['COURT','裁判'],['RIGHTS','權利'],['PEACE','和平']];
function peaceMetrics(){const vals=[peaceState.evidence,peaceState.capacity,peaceState.cooperation,peaceState.protection],flow=Math.pow(vals.reduce((p,v)=>p*Math.max(.01,v/100),1),1/4)*100;const keys=['Evidence 證據','Capacity 制度','Cooperation 合作','Protection 保護'],min=Math.min(...vals),bottleneck=keys[vals.indexOf(min)],rights=DemoKit.clamp(flow*Math.sqrt(peaceState.evidence*peaceState.protection)/100,0,100);return{flow,bottleneck,rights}}
function updatePeace(){const m=peaceMetrics();DemoKit.metric('flowOutput',`${Math.round(m.flow)}%`);DemoKit.metric('bottleneckOutput',m.bottleneck);DemoKit.metric('rightsOutput',`${Math.round(m.rights)}%`)}
const peaceController=DemoKit.animator(document.getElementById('peaceCanvas'),(ctx,w,h,t)=>{DemoKit.clear(ctx,w,h);const margin=w<560?42:70,y=h*.5,span=(w-margin*2)/(peaceLabels.length-1),nodes=peaceLabels.map((label,i)=>({x:margin+i*span,y:y+Math.sin(i*1.6)*h*.17,label}));const strengths=[peaceState.protection,peaceState.evidence,peaceState.capacity,peaceState.cooperation,(peaceState.capacity+peaceState.cooperation)/2];for(let i=0;i<nodes.length-1;i++){const a=nodes[i],b=nodes[i+1],s=strengths[i]/100,color=s<.6?'#ffcb6b':'#65dfa5';ctx.strokeStyle=color+'88';ctx.lineWidth=2+s*5;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();for(let p=0;p<3;p++){const q=(t*.18*s+p/3)%1,x=DemoKit.lerp(a.x,b.x,q),yy=DemoKit.lerp(a.y,b.y,q);ctx.fillStyle=color;ctx.shadowBlur=12;ctx.shadowColor=color;ctx.beginPath();ctx.arc(x,yy,3.5,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}}
  nodes.forEach((n,i)=>{const local=i===0?peaceState.protection:i===1?peaceState.evidence:i<4?peaceState.capacity:i===4?peaceState.cooperation:(peaceState.capacity+peaceState.cooperation)/2,color=local<60?'#ffcb6b':'#65dfa5';ctx.fillStyle='#0e1b2d';ctx.strokeStyle=color;ctx.lineWidth=3;ctx.beginPath();ctx.arc(n.x,n.y,w<560?24:34,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#eef5ff';ctx.font=`${w<560?8:10}px ui-monospace,monospace`;ctx.textAlign='center';ctx.fillText(n.label[0],n.x,n.y-2);ctx.fillStyle='#9eacc0';ctx.fillText(n.label[1],n.x,n.y+12)});const m=peaceMetrics();ctx.fillStyle='#9eacc0';ctx.textAlign='left';ctx.font='11px ui-monospace,monospace';ctx.fillText(`SYSTEM FLOW ${Math.round(m.flow)}% · BOTTLENECK ${m.bottleneck.toUpperCase()}`,18,h-22);updatePeace()});
DemoKit.range('evidence','evidenceValue',v=>`${v}%`,v=>peaceState.evidence=v);DemoKit.range('capacity','capacityValue',v=>`${v}%`,v=>peaceState.capacity=v);DemoKit.range('cooperation','cooperationValue',v=>`${v}%`,v=>peaceState.cooperation=v);DemoKit.range('protection','protectionValue',v=>`${v}%`,v=>peaceState.protection=v);DemoKit.wireButton(peaceController);document.getElementById('resetDemo').addEventListener('click',()=>{[['evidence',72],['capacity',64],['cooperation',58],['protection',76]].forEach(([id,v])=>{const el=document.getElementById(id);el.value=v;el.dispatchEvent(new Event('input'))});peaceController.reset()});updatePeace();
